import React from "react";
import HomeIcon from '@mui/icons-material/Home';
import EmailIcon from '@mui/icons-material/Email';


export const SidebarData =[
    {
        title:"Maison",
        icon:<HomeIcon/>,
        link:"/home",
    },
    {
        title:"Travail",
        icon:<EmailIcon/>,
        link:"/mail",
    },
    {
        title:"Vacance",
        icon:<HomeIcon/>,
        link:"/home",
    },
    {
        title:"Retour Vacance",
        icon:<HomeIcon/>,
        link:"/home",
    },
]
